H,W = 7,22
g = [[9]*W for _ in range(H)]
g[0][17:22] = [1]*5          # top segment
g[6][0:5] = [1]*5            # bottom segment
threes = {(2,2),(3,0),(3,3),(4,1),(4,4)}
for r,c in threes: g[r][c] = 3
# bottom-derived vertical lines: cols 0-4, from row 5 up to nearest 3 (inclusive -> 4)
for c in range(5):
    r = 5
    while r >= 0:
        if g[r][c] == 3:
            g[r][c] = 4; break
        g[r][c] = 3; r -= 1
# top-derived vertical lines: cols 17-21, rows 1..6 (no 3s there)
for c in range(17,22):
    for r in range(1,7): g[r][c] = 3
for row in g: print(row)
